import sys, numpy as np, math
sys.path.insert(0,'/workspace/submission')
from te.algorithms.sub_algorithms.mlu_backends.pdlp_mlu import PDLPMLU

def check(V, rho, mode, active=None):
    E=len(V)
    if active is None: active=np.ones(E,bool)
    s=PDLPMLU(E,rho,mode); s.active=active; s.update_F_m(V,rho=rho); s.solve()
    z=s.current_Z.copy(); h=s.current_u; t=s.current_pressure.copy()
    errs=[]
    # objective comparison with a dense scan + bisection reference
    def phi(hh):
        zz=np.minimum(V,hh)
        return hh + 0.5*rho*np.sum((zz-V)**2) if mode=='route' else 0.5*rho*np.sum((np.minimum(V,1.0)-V)**2)
    if mode=='route':
        lo,hi=0.0,max(1.0,float(np.max(V))*1.5+1)
        # ternary search on convex function
        for _ in range(200):
            m1=lo+(hi-lo)/3; m2=hi-(hi-lo)/3
            if phi(m1)<phi(m2): hi=m2
            else: lo=m1
        href=(lo+hi)/2; fref=phi(href)
        if phi(h) > fref + 1e-9*max(1,abs(fref)):
            errs.append(f'suboptimal h={h} phi={phi(h)} ref={href} {fref}')
    else:
        if abs(h-1.0)>1e-12: errs.append('admit h != 1')
    for e in range(E):
        if not active[e]:
            if z[e]!=0 or t[e]!=0: errs.append('inactive nonzero')
            continue
        if t[e] < -1e-12: errs.append(f'neg pressure {t[e]}')
        if abs(rho*(z[e]-V[e])+t[e])>1e-7: errs.append(f'identity {rho*(z[e]-V[e])+t[e]}')
        if abs(t[e]*(h-z[e]))>1e-7: errs.append(f'complementarity {t[e]*(h-z[e])}')
        if z[e]>h+1e-9: errs.append('z>h')
    if mode=='route':
        ssum=float(np.sum(t[active]))
        if ssum>1+1e-9: errs.append(f'sum t {ssum} > 1')
        if abs(h*(1-ssum))>1e-7: errs.append(f'h*(1-sum t) {h*(1-ssum)}')
    return errs, (z,h,t)

rng=np.random.default_rng(3)
bad=0
for trial in range(3000):
    E=int(rng.integers(1,9)); rho=float(rng.integers(1,9))
    style=rng.random()
    if style<0.3: V=rng.normal(size=E)*rng.choice([1e-6,1,1e4])
    elif style<0.5: V=np.round(rng.normal(size=E)*3)  # ties
    elif style<0.7: V=rng.random(size=E)*rng.choice([0.05,1.0,5.0])
    else: V=-rng.random(size=E)*2
    mode=rng.choice(['route','admit'])
    active=rng.random(E)<0.8
    if not active.any(): active[0]=True
    errs,_=check(V,rho,mode,active)
    if errs:
        bad+=1
        if bad<6: print('V',V,'rho',rho,'mode',mode,'active',active,errs[:3])
# special cases
for V,rho,mode in [(np.zeros(3),1.0,'route'),(np.array([-5.,-1.]),2.,'route'),(np.array([0.1]),1.,'route'),
                   (np.array([1e9,1e9]),8.,'route'),(np.array([0.125]),8.,'route'),(np.array([0.2,0.2]),8.,'route')]:
    errs,_=check(V,rho,mode)
    if errs: print('special',V,rho,mode,errs[:2]); bad+=1
print('controller bad',bad)
PYEOF
